<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';require_once '../includes/security/role_guard.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['airline_manager','supervisor','system_admin']);$pdo=$db->getConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['flight_id'],$_POST['status'])){try{$stmt=$pdo->prepare("UPDATE flights SET status=?,departure_time=?,arrival_time=? WHERE id=?");$stmt->execute([$_POST['status'],$_POST['departure_time'],$_POST['arrival_time'],$_POST['flight_id']]);$msg='Flight updated';}catch(Throwable $e){$msg='Unable to update flight';}}$flights=$pdo->query("SELECT f.*,a.airline_name,oa.airport_name origin,da.airport_name destination FROM flights f JOIN airlines a ON f.airline_id=a.id JOIN airports oa ON f.origin_airport_id=oa.id JOIN airports da ON f.destination_airport_id=da.id ORDER BY f.departure_time DESC LIMIT 100")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flight Management</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="../admin/dashboard.php">← Dashboard</a><h2>Flight Management</h2><?php if($msg):?><div class="alert alert-info"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="table-responsive"><table class="table table-striped bg-white"><thead><tr><th>Flight</th><th>Airline</th><th>Route</th><th>Departure</th><th>Arrival</th><th>Status</th></tr></thead><tbody><?php foreach($flights as $f):?><tr><td><?=htmlspecialchars($f['flight_number'])?></td><td><?=htmlspecialchars($f['airline_name'])?></td><td><?=htmlspecialchars($f['origin'])?> → <?=htmlspecialchars($f['destination'])?></td><td><?=htmlspecialchars($f['departure_time'])?></td><td><?=htmlspecialchars($f['arrival_time'])?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="flight_id" value="<?=intval($f['id'])?>"><input type="datetime-local" class="form-control form-control-sm" name="departure_time" value="<?=date('Y-m-d\TH:i',strtotime($f['departure_time']))?>"><input type="datetime-local" class="form-control form-control-sm" name="arrival_time" value="<?=date('Y-m-d\TH:i',strtotime($f['arrival_time']))?>"><select class="form-select form-select-sm" name="status"><?php foreach(['scheduled','boarding','departed','in_air','arrived','delayed','cancelled'] as $s):?><option value="<?=$s?>" <?=$s===$f['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></body></html>